//! Dependency-free fuzz-smoke tests for parse + lower + type-check.
//!
//! `check_source` must never panic and must report at least one diagnostic on
//! failure. Inputs are generated by a SplitMix64 PRNG (fixed seeds, so every
//! run is reproducible) and bounded in size and iteration count so each test
//! finishes well below two seconds.

use std::time::{Duration, Instant};

use pyx_frontend::check_source;

/// Small deterministic PRNG (SplitMix64).
struct SplitMix64 {
    state: u64,
}

impl SplitMix64 {
    fn new(seed: u64) -> Self {
        Self { state: seed }
    }

    fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % n as u64) as usize
    }

    fn pick<'a, T>(&mut self, items: &'a [T]) -> &'a T {
        &items[self.below(items.len())]
    }
}

/// Runs one input through the frontend and checks the public contract.
fn check(input: &str, filename: &str) {
    match check_source(input, filename) {
        Ok(_) => {}
        Err(diagnostics) => {
            assert!(
                !diagnostics.is_empty(),
                "failed check returned no diagnostics for {filename:?}"
            );
            for diagnostic in &diagnostics {
                assert_eq!(diagnostic.file, filename);
                assert!(diagnostic.line >= 1, "line numbers are 1-based");
                assert!(diagnostic.col >= 1, "column numbers are 1-based");
                assert!(!diagnostic.code.is_empty());
            }
        }
    }
}

/// Asserts the test stayed inside its time budget.
fn budget(start: Instant, label: &str) {
    let elapsed = start.elapsed();
    assert!(
        elapsed < Duration::from_secs(2),
        "{label} took {elapsed:?}, over the 2 s smoke budget"
    );
}

/// Text fragments that stress the lexer/parser rather than forming a program.
const FRAGMENTS: &[&str] = &[
    "def", "class", "return", "lambda", "yield", "await", "async", "for", "while", "if", "else",
    "elif", "try", "except", "finally", "with", "import", "from", "as", "global", "nonlocal",
    "match", "case", "->", "**", "//", ":=", "@", "...", "\\", "\\\n", "'''", "\"\"\"", "f'",
    "f\"", "b'", "r'", "#", "\t", " ", "\n", "\r\n", "\r", "\x0b", "\x0c", "\0", "0x", "1_000",
    "1e", ".5", "self", "None", "True", "False", "print", "(", ")", "[", "]", "{", "}", ":", ",",
    ";", "+", "-", "*", "/", "%", "&", "|", "^", "~", "!", "=", "<", ">", "0b", "0o",
];

/// Interesting Unicode scalars: identifiers, combining marks, RTL, emoji,
/// compatibility forms and the replacement character.
const SCALARS: &[char] = &[
    'a',
    'Z',
    '0',
    '_',
    'é',
    'Å',
    'Ω',
    '中',
    'א',
    'ا',
    'क',
    'ก',
    '\u{0301}',
    '\u{200b}',
    '\u{200f}',
    '\u{202e}',
    '\u{2066}',
    '\u{feff}',
    '😀',
    '👨',
    '\u{1f1e6}',
    '\u{10ffff}',
    '\u{fffd}',
    '\u{e000}',
    '\u{0378}',
    '\u{2145}',
    '\u{2160}',
    '·',
    '˙',
];

/// Fragments joined randomly with random separators.
fn random_source(rng: &mut SplitMix64, parts: usize) -> String {
    let mut out = String::new();
    for _ in 0..parts {
        out.push_str(rng.pick(FRAGMENTS));
        if rng.below(2) == 0 {
            out.push_str(rng.pick(&[" ", "", "\n", "\t", "  "]));
        }
        if out.len() > 768 {
            break;
        }
    }
    out
}

#[test]
fn random_token_soup_never_panics() {
    let start = Instant::now();
    for seed in [1u64, 2, 3, 0x5EED, 0xDEAD_BEEF, u64::MAX] {
        let mut rng = SplitMix64::new(seed);
        for case in 0..60 {
            let parts = 1 + rng.below(24);
            let source = random_source(&mut rng, parts);
            check(&source, &format!("fuzz-{seed}-{case}.py"));
        }
    }
    budget(start, "token soup");
}

#[test]
fn random_unicode_source_never_panics() {
    let start = Instant::now();
    for seed in [7u64, 11, 0xCAFE, 0xF00D] {
        let mut rng = SplitMix64::new(seed);
        for case in 0..50 {
            let mut source = String::new();
            let len = rng.below(400);
            for _ in 0..len {
                match rng.below(5) {
                    0 => source.push(*rng.pick(SCALARS)),
                    1 => source.push_str(rng.pick(FRAGMENTS)),
                    2 => source.push('x'),
                    3 => source.push(' '),
                    _ => source.push('\n'),
                }
            }
            // Filenames themselves may carry non-ASCII: they flow into
            // diagnostics and tracebacks verbatim.
            let filename = format!("fuzz-\u{00e9}-{seed}-{case}.py");
            check(&source, &filename);
        }
    }
    budget(start, "unicode soup");
}

/// A valid program that mutations start from.
const SEED_PROGRAM: &str = "\
def add(a: int, b: int) -> int:
    return a + b

def describe(value: str) -> str:
    match value:
        case \"\" | None:
            return \"empty\"
        case _:
            return f\"{value!r}: {len(value)}\"

items = [add(i, i * 2) for i in range(6)]
total = sum(items)
print(describe(\"pyx\"), total)
";

#[test]
fn mutations_of_a_valid_program_never_panic() {
    let start = Instant::now();
    let bytes: Vec<char> = SEED_PROGRAM.chars().collect();
    for seed in [13u64, 17, 0xBEEF] {
        let mut rng = SplitMix64::new(seed);
        for case in 0..60 {
            let mut edited = bytes.clone();
            for _ in 0..1 + rng.below(6) {
                if edited.is_empty() {
                    break;
                }
                let index = rng.below(edited.len());
                match rng.below(3) {
                    0 => {
                        edited.remove(index);
                    }
                    1 => edited.insert(index, *rng.pick(&['(', ')', ':', '\'', '\0', '\\', ' '])),
                    _ => {
                        edited[index] = *rng.pick(SCALARS);
                    }
                }
            }
            let source: String = edited.into_iter().collect();
            check(&source, &format!("mutant-{seed}-{case}.py"));
        }
    }
    budget(start, "mutations");
}

#[test]
fn pathological_corpus_never_panics() {
    let start = Instant::now();
    let corpus = [
        String::new(),
        "\0".to_string(),
        "\u{feff}".to_string(),
        "\r\n\r\n".to_string(),
        "\u{202e}".to_string(),
        "x =".to_string(),
        "def (".to_string(),
        "f\"{".to_string(),
        "'''".to_string(),
        "\\".to_string(),
        format!("x = {}", "(".repeat(2_000)),
        format!("x = [{}]", "1,".repeat(2_000)),
        format!("x = \"{}\"", "\u{1f600}".repeat(1_000)),
        format!("# {}", "\u{fffd}".repeat(2_000)),
        format!("{}x = 1", " ".repeat(4_000)),
    ];
    for (index, source) in corpus.iter().enumerate() {
        check(source, &format!("pathological-{index}.py"));
    }
    budget(start, "pathological corpus");
}
